-- GENERATED by `wfj generate` from data/gossip/gossip-23.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["2302157af18a785b"] = { "Il forziere dell'⟦SI:7=IR:7⟧ si apre, facendo scattare un allarme ben udibile.", "." },
  ["2307e28308bc81e6"] = { "Il tuo spirito è puro, {name}.", "." },
  ["2308d888f87578b6"] = { "Dov'è l'anziano Mistwalker?", "." },
  ["230dd393cb501c68"] = { "Come osi!", "." },
  ["2315435bbf84f45e"] = { "I nostri preparativi procedono come previsto, padrone.", "." },
  ["2316c67cc8d03d48"] = { "C'è altro che dovrei sapere sui Terrigeni?", "." },
  ["231a027f287e819d"] = { "Sono qui a ritirare il tuo rapporto.", "." },
  ["231ab37d4c6ada71"] = { "Miserabili sacchi di carne per vermi, sapete fare di meglio, ora dimostratelo!", "." },
  ["231fc41ee92c3712"] = { "Vedi, il nuovo shredder della S.P.R. & Co. è migliore del mio ultimo modello, dalle mani intercambiabili alle impugnature di comando! Il mio capo mi ha dato una scadenza piuttosto rigida, ma io e i miei ragazzi non siamo riusciti a inventarci niente.\n\nNon funzionava nulla, così abbiamo deciso di \"prendere in prestito\" uno dei loro prototipi. Ho mandato Wizzlecrank alla ⟦Sludge Fen=Palude Fangosa⟧ a rubarne uno, ma non è ancora tornato!", "." },
  ["23228672524b7324"] = { "Ho quasi abbastanza rifornimenti per potenziare le nostre truppe.", "." },
  ["23256d871509e288"] = { "E adesso che c'è? Non vedi che ho parecchio da fare?", "." },
  ["233069f94314d11e"] = { "Ti tengo d'occhio, {race}.", "." },
  ["23327e64828872ba"] = { "Non addestro quelli come te, {class}.", "." },
  ["2336ac04c907ddb8"] = { "No, Ulathek. Lui conosce il tuo segreto. Sa che complotti con lord Hel'nurath di Xoroth.", "." },
  ["2339c993414fba4b"] = { "Schiaccio deboli come te ogni giorno! Fatti sotto!", "." },
  ["2344417af8ca62b3"] = { "Oh no! I draghi fatati catturati non ce l'hanno fatta. Cosa facciamo?", "." },
  ["23469fa273f901b7"] = { "Devi lasciare il bar!", "." },
  ["2346b1df4b7931cd"] = { "Il mio popolo non ti conosce. Il kodo è una cavalcatura possente, frutto dell'amore e delle cure della mia gente; non lo si concede agli stranieri. Finché non avrai reputazione Osannato presso gli anziani di ⟦Thunder Bluff=Picco del Tuono⟧, non posso venderti un kodo.", "." },
  ["2353a2049c378bbc"] = { "Ora siete miei, bambini. Crescerete e diventerete una parte forte dell'Orda!", "." },
  ["2357ac0b58311782"] = { "Furono i luogotenenti di Ragnaros, Geddon e Garr, a perpetrare il tradimento contro il mio Signore. Thunderaan fu colto alla sprovvista.", "." },
  ["235d92a861d61050"] = { "Cercavo materiali per costruire la mia ultima e più grande invenzione, l'unità shredder portatile a controllo remoto, quando questi troll mi sono saltati addosso con le clave, trascinandomi nelle profondità della loro caverna.\n\nRiportami al sicuro e darò il mio aiuto alla tua causa, {race}.", "." },
  ["235e7e9d4d50e360"] = { "Dov'è il primo maresciallo Teravaine?", "." },
  ["2366a96e95fa5ed1"] = { "Non vediamo di buon occhio i malfattori, {race}.", "." },
  ["236cf5391ec0ce33"] = { "Oh, eccoti qui, Rockbiter! Scusa, lo so che non dovrei allontanarmi.", "." },
  ["236db6eabe942c2f"] = { "Ora dobbiamo proseguire.", "." },
  ["23710c4e3f89e6ea"] = { "Ottimo addomesticamento, {name}! Stai già diventando <esperto/esperta>.", "." },
  ["2371df0931c01c0b"] = { "Certo, ti dirò la frase. Basta che non debba avvicinarmi a Tirth!", "." },
  ["2372708eafcd7f7b"] = { "Non puoi cavalcare in questa forma.", "." },
  ["23730424ca48ac17"] = { "Mmh, curioso... Si interrompe di colpo. A Tanaris i Qiraji documentano lo scontro con un drago di bronzo. Manca molto... Bisogna trovare altre informazioni! Di certo stanno progettando di invadere di nuovo Kalimdor!", "." },
  ["23737085fa9c8b6a"] = { "Addio, e che i nostri antenati siano sempre con te!", "." },
  ["2373cc37c8b38ac5"] = { "Quest'orso vaga lungo un percorso vicino al Sentiero di Graffiofondo, a ovest del ⟦Mystral Lake=Lago Mystral⟧ e dell'avamposto dell'⟦Alliance=Alleanza⟧ del ⟦Silverwind Refuge=Rifugio Vento Argentato⟧. Anche se è la più facile delle tre creature che affronterai nella Caccia di ⟦Ashenvale=Valtetra⟧, non va preso alla leggera. La sua presenza è una minaccia costante per i viaggiatori che transitano tra ⟦Ashenvale=Valtetra⟧ e le ⟦Stonetalon Mountains=Vette di Petrartiglio⟧.", "." },
  ["237a603e1a6defb7"] = { "Allora? M'hai interrotto, perciò spero per te che tu abbia un dannatissimo buon motivo.", "." },
  ["238a10a100755107"] = { "Ah, tu non trovato, vero capo? Forse storia dei vecchi tempi è storia brutta... difficile credere che elfo inquietante può rubare a re Gordok!", "." },
  ["238d5e552da96151"] = { "Di nuovo la campana, che dolce suono.", "." },
  ["2393e0b562f388b3"] = { "Se riusciamo a trattenerli adesso, di sicuro ce la faremo.", "." },
  ["23992f365e672ca0"] = { "Ecco. È fatto.", "." },
  ["23a5f4f0a6d8ff8f"] = { "Hai la voce rauca a forza di urlare, eh? Trova la casa d'aste di Orgrimmar nella ⟦Valley of Strength=Valle della Forza⟧.", "." },
  ["23b2cb7f9bfab022"] = { "Ho notato un fuoco su quell'isola laggiù. E anche un umano. Andiamo a dare un'occhiata, {name}.", "." },
  ["23ba75454407d2bb"] = { "Che fortuna, sono ancora in vita!", "." },
  ["23bc2cde1276cd2d"] = { "Il tuo messaggio ci è arrivato, comandante, ma il nostro intervento qui non è affatto autorizzato dal gran crociato.", "." },
  ["23c5d74f4791cf02"] = { "Salute, <avventuriero/avventuriera>. Sono Rin'wosho, mercante di Zuldazar. Vengo dai ⟦South Seas=Mari del Sud⟧ e porto molte merci e oggetti esotici dalla mia patria.\n\nForse, se dimostrerai il tuo valore alla mia tribù, farò baratti con te. E se hai degli Emblemi dell'Onore della mia tribù, forse baratteremo ancora di più.", "." },
  ["23c954791197d66d"] = { "Parlami del cannone.", "." },
  ["23d2426fd29ed2bf"] = { "Ho perso il mio ⟦Ring of Unspoken Names=Anello dei Nomi Innominati⟧. Puoi sostituirmelo?", "." },
  ["23d7f2890671e1e4"] = { "Il tuo sangue sarà il catalizzatore del ritorno degli Dei Antichi!", "." },
  ["23d993f712b0a911"] = { "Hai trovato i termitai, {name}? Ho sentito che a ⟦Plaguewood=Malaselva⟧ sono dappertutto.", "." },
  ["23dc5d661041e5b2"] = { "[PH] Ok, me ne vado... ci vediamo nella tana di Ragnaros... a dopo", "." },
  ["23dd4b70ec0e2e0c"] = { "Spero che tu abbia fatto soffrire un po' la ⟦Scarlet Crusade=Crociata Scarlatta⟧ prima di rubare il libro.\n\nLe mie opinioni sulla loro gente non sono infondate. Un tempo la Crociata sarà anche stata seguace della Luce, ma ora cerca di distruggere qualsiasi creatura che non abbia abbracciato la sua religione. Credono che tutti i non morti, Reietti o no, debbano essere purificati, e che chi viaggia nelle loro terre debba essere pazzo o in balia della potente magia dei non morti. Idioti. Idioti e stolti, tutti quanti.", "." },
  ["23e64d1f34a71555"] = { "Vieni, {name}. Il lago è appena dopo la curva.", "." },
  ["23e973225c96986f"] = { "Che succede qui? Piznik! Lo sapevo che non dovevamo lasciarti restare!", "." },
  ["23f61b227cbc3b2f"] = { "Ehi, Vi'el, fammi vedere la tua merce!", "." },
  ["23fca8c6a1cfe773"] = { "Gli umani si erano presi gran parte della palude di ⟦Dustwallow Marsh=Acquemorte⟧, ma il clan Mazzapietra, con il nostro aiuto, è riuscito a respingerli.", "." },
  ["23fd961c559963f6"] = { "Giustizia è fatta!", "." },
})
